insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('f2998627-1c88-4ed3-a2f4-cfd1bd5e0575', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<p>Cuidado con lo que yo llamo FEMINISMO LIGHT. Es la idea de la igualdad femenina condicional, recházala de plano, por favor. Es una idea vacua, fallida y tranquilizadora. Ser feminista es como estar embarazada, lo estás o no lo estás. O crees en plena igualdad entre hombres y mujeres o no, feminismo light emplea analogías como «Él es la cabeza y tú el cuello». O «Él conduce, pero tú viajas en el asiento delantero». Aún más preocupante es que dentro del FEMINISMO LIGHT, está la idea de que los hombres son superiores por naturaleza, pero deben «tratar bien a las mujeres». No. No. No.</p><p>El bienestar de una mujer debe basarse en algo más que la benevolencia masculina. El FEMINISMO LIGHT recurre al lenguaje de la «permisión». Theresa May es la primera ministra británica y un diario progresista de su país describía así a su marido: «Philip May es conocido en la política por ser un hombre que ha dado un paso atrás para permitir que sea su mujer, Theresa, quien brille». Permitir. Démosle la vuelta. Theresa May ha permitido a su marido brillar. ¿Tiene sentido? Si Philip May fuera primer ministro quizá diríamos que su esposa le ha «apoyado» desde un segundo plano o que está «detrás de él» o «a su lado», pero jamás que le ha «permitido» brillar [...] la triste verdad es que, nuestro mundo está repleto de hombres y mujeres a quienes no les gustan las mujeres poderosas. Nos han condicionado tanto con que el poder es masculino, que una mujer poderosa parece una aberración. Y como tal la vigilan. De una mujer poderosa nos preguntamos ¿Es humilde? ¿Sonríe? ¿Es lo bastante agradecida? ¿Tiene también su lado doméstico? Preguntas que no nos planteamos de los hombres poderosos, lo cual prueba que no nos incomoda el poder en sí, sino las mujeres. Juzgamos más duramente a las mujeres poderosas que a los hombres poderosos. Y el feminismo light lo hace posible.</p><p class="ctx-fuente"><small>Ngozi Adichie, Ch. (2017). Querida Ijeawele. Cómo educar en el feminismo. Colombia: Literatura Random House.</small></p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('9cb858cb-291c-492c-b32a-f6270f022925', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<p><b>Un compañero en la balsa</b></p><p>Casi a las dos me sentí completamente agotado. Crucé los remos y traté de dormir. En ese momento había aumentado la sed. El hambre no me molestaba. Me molestaba la sed. Me sentí tan cansado que apoyé la cabeza en el remo y me dispuse a dormir. Entonces fue cuando vi, sentado en la cubierta del destructor, al marinero Jaime Manjarrés, que me mostraba con el índice la dirección del puerto. Jaime Manjarrés, bogotano, es uno de mis amigos más antiguos en la marina, con frecuencia pensaba en los compañeros que trataron de abordar la balsa [...] Sin embargo, tan pronto como cerraba los ojos aparecía Jaime Manjarrés, sonriente, primero señalándome la dirección del puerto y luego sentado en el comedor frente a mí, con un plato de frutas y huevos revueltos en la mano. Al principio fue un sueño. Cerraba los ojos, dormía durante breves minutos y aparecía siempre, puntual y en la misma posición, Jaime Manjarrés. Por fin decidí hablarle, no recuerdo qué le pregunté en esa primera ocasión.</p><p>No recuerdo tampoco qué me respondió. Pero sé que estábamos conversando en la cubierta y de pronto vino el golpe de la ola, la ola fatal de las 11:55, y desperté sobresaltado, agarrándome con todas mis fuerzas al enrejado para no caer al mar. Pero antes del amanecer se oscureció el cielo. No pude dormir más porque me sentía agotado, incluso para dormir. En medio de las tinieblas dejé de ver el otro extremo de la balsa. Pero seguí mirando hacia la oscuridad, tratando de penetrarla. Entonces fue cuando vi perfectamente, en el extremo de la borda, a Jaime Manjarrés, sentado, con su uniforme de trabajo pantalón y camisa azules, y la gorra ligeramente inclinada sobre la oreja derecha, en la que se leía claramente, a pesar de la oscuridad: «A. R. C. Caldas».</p><p>—Hola —le dije sin sobresaltarme. Seguro de que Jaime Manjarrés estaba allí. Seguro de que allí había estado siempre. Si esto hubiera sido un sueño no tendría ninguna importancia. Sé que estaba completamente despierto, completamente lúcido, y que oía el silbido del viento y el ruido del mar sobre mi cabeza. Sentía el hambre y la sed. Y no me cabía la menor duda de que Jaime Manjarrés viajaba conmigo en la balsa.<br>—¿Por qué no tomaste bastante agua en el buque? —me preguntó.<br>—Porque estábamos llegando a Cartagena —le respondí. Estaba acostado en la popa con Ramón Herrera. No era una aparición. Yo no sentía miedo. Me parecía una tontería que antes me hubiera sentido solo en la balsa, sin saber que otro marinero estaba conmigo.<br>—¿Por qué no comiste? —me preguntó Jaime Manjarrés.<br>Recuerdo perfectamente que le dije:<br>—Porque no quisieron darme comida. Pedí manzanas y helados y no quisieron dármelos. No sé dónde los tenían escondidos.<br>[...] Pero ya no estaba ahí. Se había ido. Yo estaba solo en la balsa y las luces del puerto eran los primeros rayos del sol. Los primeros rayos de mi tercer día de soledad en el mar.</p><p class="ctx-fuente"><small>Tomado de: García Márquez, G. Relato de un náufrago, pp. 44–45. Bogotá: Oveja Negra.</small></p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('144cd6d7-a0c6-437d-99eb-179ffded760e', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<p><b>El origen del mal</b></p><p>En medio de un bosque vivía un ermitaño que entendía el lenguaje de las fieras y hasta podía conversar con ellas. En una ocasión en que descansaba debajo de un árbol, se cobijaron allí, para pasar la noche, un cuervo, un palomo, un ciervo y una serpiente y empezaron a discutir sobre el origen del mal.</p><p>—El mal procede del hambre —declaró el cuervo—. Cuando uno come hasta hartarse, las cosas se le antojan de color de rosa. Pero, amigos, si durante días no se prueba bocado, cambia la situación y ya no parece tan hermosa la naturaleza. ¡Qué desasosiego! ¡Qué intranquilidad siente uno! Y si vislumbro un buen pedazo de carne, me abalanzo sobre él, ciegamente; ni palos ni piedras, ni lobos enfurecidos serían capaces de hacerme soltar la presa. ¡Cuántos perecemos como víctimas del hambre! No cabe duda de que el hambre es el origen del mal.</p><p>El palomo intervino: El mal no proviene del hambre, sino del amor. Si viviéramos solos, sin hembras, sobrellevaríamos las penas. Mas ¡ay!, vivimos en pareja y amamos tanto a nuestra compañera que no hallamos un minuto de sosiego, siempre pensando en ella. Y cuando se aleja un poco de nuestro lado, nos sentimos como perdidos y nos tortura la idea de que un gavilán la haya despedazado. Empezamos a buscarla por doquier, con loco afán; y si desaparece, uno no come ni bebe, no hace más que buscarla y llorar. ¡Cuántos mueren así entre nosotros! Ya ven que todo el mal proviene del amor.</p><p>—No, el mal no viene ni del hambre ni del amor —arguyó la serpiente—. El mal viene de la ira. Si viviésemos tranquilos, entonces todo iría bien. Pero, cuando algo se arregla de modo distinto a como quisiéramos, todo nos ofusca. Sólo pensamos en descargar nuestra ira en el primero que encontramos. Entonces, como locos, nos retorcemos, tratando de morder a alguien. En tales momentos, no se tiene piedad de nadie; mordería uno a su propia madre, podríamos comernos a nosotros mismos. Sin duda alguna, todo el mal viene de la ira.</p><p>El ciervo no fue de este parecer. —No; no es de la ira ni del amor ni del hambre de donde procede el mal, sino del miedo. Si fuera posible no sentir miedo, todo marcharía bien. Podemos defendernos de un animal pequeño, con nuestros cuernos, y la huida nos preserva de los grandes. Pero es imposible no sentir miedo. Apenas cruje una rama en el bosque o se mueve una hoja, temblamos de terror. El corazón palpita, como si fuera a salirse del pecho, y echamos a correr. Siempre estamos alerta, llenos de terror. No hay modo de disfrutar de un poco de tranquilidad. Por eso el origen del mal está en el miedo.</p><p>Finalmente intervino el ermitaño y dijo lo siguiente:<br>—No es el hambre, el amor, la ira ni el miedo, la fuente de nuestros males, sino nuestra propia naturaleza: ella es la que engendra el hambre, el amor, la ira y el miedo.</p><p class="ctx-fuente"><small>Tomado y adaptado de: Tolstoi, L. El origen del mal. Recuperado de ciudadseva.com/texto/el-origen-del-mal/</small></p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('cf940cce-9c38-483b-8579-c491da3e2ca4', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/lc/s21-q68-secuestros.webp" style="min-width:800px" loading="lazy" alt="Infografía de estadísticas del conflicto armado colombiano. Entre 1958 y 2012 murieron 218.094 personas: 40.787 combatientes y 177.207 civiles. Entre 1970 y 2010 se registran 27.023 víctimas de secuestro: 24.482 atribuidas a guerrillas y 2.541 a grupos paramilitares. Un mapa ubica municipios en estado crítico, con más puntos en el norte: Fundación, Valledupar, Curumaní, Aguachica, Ocaña, Arauca, San Pablo, Medellín, Quibdó, San Luis, Bucaramanga, Bogotá, Villavicencio, Cali y San Vicente del Caguán."><figcaption>Desliza para ver la infografía completa. Centro Nacional de Memoria Histórica; cifras de secuestros: Cifras y Conceptos.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('db8b8e5a-c752-436c-bc83-b091c434c17e', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<p><b>El llanto de un hombre</b></p><p>Los hombres. Seres insensibles, machos verdaderos superiores a las mujeres que lloran y sienten. Sin derecho a la ternura, sin permiso para sentir afecto por otros hombres, sin permiso para expresar verbalmente afecto o amor a las mujeres. Con la prohibición social contundente de decir «te quiero» a sus hijos e hijas, los hombres de mi cultura, moldeados no al fuego sino al frío, con troqueles de acero para que sean hombres supuestamente verdaderos, es decir conforme a los permisos culturales y las prohibiciones sociales que no los dejan ser humanos, solo hombres. Hombres de hierro y acero incrustados en diamantes. Nada de endebles de carne y hueso. Esto es para las mujeres.</p><p>¡Qué horrible! Un día vi llorar en la «pantalla» a un portero profesional de fútbol. No parecía un hombre del modelo occidental colombiano. Parecía troquelado en otro molde, traído no sé de dónde. Y lo más terrible es que es verdaderamente colombiano y famoso deportista. Es un ídolo de multitudes, pero llora. Y no se ha escondido después de que todo el mundo lo vio llorando como un niño, o quizás, como una niña en la percepción.</p><p>¿Y qué es el llanto? ¿Un simple río de lágrimas? ¿La expresión de rictus faciales que afean a las personas? El llanto es mucho más. La expresión profundamente humana del dolor físico o del alma y el corazón en adultos vivientes y con sentimientos naturales, el llanto es la proclama de nuestra capacidad de sentir, de amar con ardor y santo desespero, de sufrir por nuestro propio pesar y por el dolor de los demás. Es un privilegio humano que supera el chillido de los animales y que manifiesta esa condición única de los humanos con su capacidad de ser conscientes del dolor y la alegría.</p><p>Qué horrible es la prohibición de llorar. Qué castrante es no poder derramar una o muchas lágrimas en presencia de otros hombres y mujeres. Nos roba la capacidad de expresar algunos de los más humanos de nuestros sentimientos, de revelar con la transparencia de una lágrima la ternura de que somos capaces los machos humanos. ¡Nada más bello que un hombre llorando! Es un testimonio de que es una persona humana, con sentimientos, escapado del macho artificial para ser el hombre real y valioso que sabe tanto de coraje y valor como de amor, ternura y dolor.</p><p>Todo hombre que llora merece un monumento. Monumento a la masculinidad con corazón. Al humanismo. Al sentimiento. A la auténtica hombría. A la revolución de la ternura. Atravesarse a llorar, contradiciendo los mandatos, tiranos de la cultura, merece mucho más que una mención de honor. El llanto de un hombre es un monumento viviente, mejor que los de piedra y bronce.</p><p class="ctx-fuente"><small>Tomado y adaptado de: Giraldo Neira, O. (2003). El llanto de un hombre. En Los héroes también lloran: por una auténtica masculinidad.</small></p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('bcdbf032-a8f9-4d07-a24b-bdb85c0a7566', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<p><b>Muertos de hambre</b></p><p>Me hacen falta muchas cosas pero no sé cuáles son. Desconecté, como un módulo desprendido de una nave, y orbito un planeta que soy yo misma, mudo, sordo, a veces ciego. Con un núcleo en llamas.</p><p>Ayer bajé a la calle. Tapabocas, carro de compras, zapatos de andar por ahí. En el umbral del edificio había un hombre desastroso, con varias bolsas en las que llevaba lo que tenía para vivir en la calle. Conozco a los mendigos del barrio. Este era uno de los nuevos. Lo saludé, le pregunté qué necesitaba. Me dijo: «Nada, estoy bien». Me quedé azorada. ¿De verdad estaba bien?, ¿cómo era posible? No insistí y me fui a hacer las compras. Cuando volví, el hombre ya no estaba.</p><p>Oxfam Internacional publicó un informe según el cual la pobreza causada por la pandemia será más mortífera que el virus: «Según las estimaciones, en 2019 había 821 millones de personas en situación de inseguridad alimentaria, de las cuales aproximadamente 149 millones sufrían hambrunas de nivel de crisis (...) El Programa Mundial de Alimentos estima que el número de personas que sufren hambrunas de nivel de crisis se incremente hasta alcanzar los 270 millones antes de que acabe el año. Esto significa que, antes de 2021, podrían morir de hambre entre 6.000 y 12.000 personas al día a consecuencia de los impactos sociales y económicos de la pandemia».</p><p>He escuchado demasiadas veces esa frase de ceguera descomunal: «Esta pandemia demuestra que el virus no discrimina». ¿No discrimina? El nuevo mendigo no ha vuelto a aparecer. Yo sigo haciendo mis compras. Con tarjeta de crédito. Y, sumida en la patética nostalgia por todo lo que era demasiado, que a veces parecía tan poco y a veces incluso parecía molesto, supongo que olvidaré al hombre mañana, como olvidaré las cifras de los muertos de hambre.</p><p class="ctx-fuente"><small>Tomado y adaptado de: Guerriero, L. (6 de septiembre de 2020). Muertos de hambre. El País.</small></p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('8f87e14e-20e5-4ace-a7cc-21b7c243067e', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<p>La edad adulta trae consigo la ilusión perniciosa del control, y acaso depende de ella. Quiero decir que es ese espejismo de dominio sobre nuestra propia vida lo que nos permite sentirnos adultos, pues asociamos la adultez con la autonomía, el soberano derecho a determinar lo que va a sucedernos enseguida. El desengaño viene más pronto o más tarde, pero viene siempre, no falta a la cita, nunca lo ha hecho. Cuando llega lo recibimos sin demasiada sorpresa, pues nadie que viva lo suficiente puede sorprenderse de que su biografía haya sido moldeada por eventos lejanos, por voluntades ajenas, con poca o ninguna participación de sus propias decisiones. Esos largos procesos que acabarán por toparse con nuestra vida —a veces para darle el empujón que necesitaba, a veces para hacer estallar en pedazos nuestros planes más espléndidos— suelen estar ocultos como corrientes subterráneas, como meticulosos desplazamientos de las capas tectónicas, y cuando por fin se da el terremoto invocamos las palabras que hemos aprendido a usar para tranquilizarnos, ACCIDENTE, CASUALIDAD, a veces DESTINO... Lo sabemos, lo sabemos bien; y sin embargo siempre da algo de pavor cuando alguien nos revela esa cadena que nos ha convertido en lo que somos, siempre desconcierta constatar, cuando es otra persona quien nos trae la revelación, el poco o ningún control que tenemos sobre nuestra experiencia.</p><p class="ctx-fuente"><small>Tomado de: Vásquez, J. G. (2011). El ruido de las cosas al caer. Madrid: Alfaguara.</small></p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('43e632cc-0850-4ff9-b5fb-948bd838da7c', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<p><b>Del deber de la desobediencia civil (1849)</b></p><p>Creo de todo corazón en el lema «El mejor gobierno es el que tiene que gobernar menos», y me gustaría verle hacerse efectivo más rápida y sistemáticamente. Bien llevado, finalmente resulta en algo en lo que también creo: «El mejor gobierno es el que no tiene que gobernar en absoluto». Y cuando los pueblos estén preparados para ello, ese será el tipo de gobierno que tengan. En el mejor de los casos, el gobierno no es más que una conveniencia, pero en su mayoría los gobiernos son inconvenientes, y todos han resultado serlo en algún momento. Las objeciones que se han hecho a la existencia de un ejército permanente, que son varias y de peso, y que merecen mantenerse, pueden también por fin esgrimirse en contra del gobierno, el ejército permanente es solo el brazo del gobierno establecido. El gobierno en sí, que es únicamente el modo escogido por el pueblo para ejecutar su voluntad, está igualmente sujeto al abuso y la corrupción antes de que el pueblo pueda actuar a través suyo. Somos testigos de la actual guerra con México, obra de unos pocos individuos comparativamente, que utilizan como herramienta al gobierno actual; en principio, el pueblo no habría aprobado esta medida. Pero, para hablar en forma práctica y como ciudadano, a diferencia de aquellos que se llaman «antigobiernistas». Yo pido no como antigobiernista sino como ciudadano, y de inmediato, un mejor gobierno. Permítasele a cada individuo dar a conocer el tipo de gobierno que lo impulsaría a respetarlo y eso ya sería un paso ganado para obtener ese respeto. Después de todo, la razón práctica por la cual, una vez que el poder está en manos del pueblo, se le permite a una mayoría, y por un período largo de tiempo, regir, no es porque esa mayoría esté tal vez en lo correcto, ni porque le parezca justo a la minoría, sino porque físicamente son los más fuertes. Pero un gobierno en el que la mayoría rige en todos los casos no se puede basar en la justicia. No es deseable cultivar respeto por la ley más de por lo que es correcto. La única obligación a la que debo someterme es a la de hacer siempre lo que creo correcto. La ley nunca hizo al hombre un ápice más justo; y a causa del respeto por ella, aún el hombre bien dispuesto se convierte a diario en un agente de la injusticia.</p><p class="ctx-fuente"><small>Tomado y adaptado de: Thoreau, D. (1849). Del deber a la desobediencia civil. Recuperado de thoreau.eserver.org/spanishcivil.html</small></p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('a58f6f34-d6f2-47fe-a98c-58068a6e78ac', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<p>[...] Bajo el golpe de mi navaja Torres rejuvenecía; sí, porque yo soy un buen barbero, el mejor de este pueblo, lo digo sin vanidad. Un poco más de jabón, aquí, bajo la barbilla, sobre la manzana, sobre esta gran vena. ¡Qué calor! Torres debe estar sudando como yo. Pero él no tiene miedo. Es un hombre sereno que ni siquiera piensa en lo que ha de hacer esta tarde con los prisioneros. En cambio yo, con esta navaja entre las manos, puliendo y puliendo esta piel, evitando que brote sangre de estos poros, cuidando todo golpe, no puedo pensar serenamente. Maldita la hora en que vino, porque yo soy un revolucionario pero no soy un asesino. Y tan fácil como resultaría matarlo. Y lo merece. ¿Lo merece? No, ¡qué diablos! Nadie merece que los demás hagan el sacrificio de convertirse en asesinos. ¿Qué se gana con ello? Pues nada. Vienen otros y otros y los primeros matan a los segundos y estos a los terceros y siguen y siguen hasta que todo es un mar de sangre. Yo podría cortar este cuello, así, ¡zas! No le daría tiempo de quejarse y como tiene los ojos cerrados no vería ni el brillo de la navaja ni el brillo de mis ojos. Pero estoy temblando como un verdadero asesino. De ese cuello brotaría un chorro de sangre sobre la sábana, sobre la silla, sobre mis manos, sobre el suelo. Tendría que cerrar la puerta. Y la sangre seguiría corriendo por el piso, tibia, imborrable, incontenible, hasta la calle, como un pequeño arroyo escarlata. Estoy seguro de que un golpe fuerte, una honda incisión, le evitaría todo dolor. No sufriría. Y qué hacer con el cuerpo? ¿Dónde ocultarlo? Yo tendría que huir, dejar estas cosas, refugiarme lejos bien lejos. Pero me perseguirían hasta dar conmigo, «El asesino del capitán Torres. Lo degolló mientras le afeitaba la barba. Una cobardía». Y por otro lado «El vengador de los nuestros, un nombre para recordar (aquí mi nombre). Era el barbero del pueblo. Nadie sabía que él defendía nuestra causa...». ¿Y qué? ¿Asesino o héroe? [...]</p><p>Pero yo no quiero ser un asesino, no señor. Usted vino para que yo lo afeitara. Y yo cumplo honradamente con mi trabajo, no quiero mancharme de sangre. De espuma y nada más. Usted es un verdugo y yo no soy más que un barbero. Y cada cual en su puesto. Eso es. Cada cual en su puesto. La barba había quedado limpia, pulida y remojada. El hombre se incorporó para mirarse en el espejo. Se pasó las manos por la piel y la sintió fresca y nueva.</p><p>«Gracias», dijo. Se dirigió al ropero en busca del cinturón, de la pistola y del sombrero. Yo debía estar muy pálido y sentía la camisa empapada. Torres concluyó de ajustar la hebilla, rectificó la posición de la pistola en la funda y luego de alisarse maquinalmente los cabellos, se puso el sombrero. Del bolsillo del pantalón extrajo unas monedas para pagarme el importe del servicio. Y empezó a caminar hacia la puerta. En el umbral se detuvo un segundo y volviéndose me dijo:<br>«Me habían dicho que usted me mataría. Vine para comprobarlo. Pero matar no es fácil. Yo sé por qué se lo digo». Y siguió calle abajo.</p><p class="ctx-fuente"><small>Tomado y adaptado de: Téllez, H. (1984). Espuma y nada más. En Cenizas para el viento y otras historias.</small></p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('d8ccd6ef-aad0-45c9-a846-368aa2803e83', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<p><b>Tiburón de Groenlandia</b></p><p>Se cree que el tiburón de Groenlandia que nació en 1505. Un estudio publicado en la revista National Geographic sostiene que es el vertebrado más longevo de la Tierra.</p><p>Según los especialistas, se puede conocer la edad de este tiburón analizando la composición de sus ojos. Usando ese método, un grupo de investigadores evaluó a 28 tiburones de Groenlandia y encontró que tenían entre 272 y 512 años. La esperanza de vida promedio de las especies es de 392 años, pero los investigadores estimaron que uno de los tiburones podría tener hasta 615 años.</p><p>El tiburón de Groenlandia es una de las criaturas que se alimenta de carne más grandes del planeta. Su crecimiento es lento: aumenta su tamaño aproximadamente un centímetro por año y puede alcanzar más de cinco metros. Cuando el equipo de investigación encontró un espécimen de 550 centímetros reconocieron que habían encontrado un tesoro del reino animal.</p><p>El tiburón de Groenlandia es una especie característica del océano Ártico, aunque también habita las regiones del océano Atlántico. «Miles de ellos acaban capturados accidentalmente en el Atlántico norte, por lo que espero que nuestro estudio sirva para prestar mayor atención a esta especie», declaró Julius Nielsen, de la Universidad de Copenhague.</p><p>«Tendemos a pensar que en general los animales vertebrados viven aproximadamente tanto como los seres humanos, entre 50 o 100 años», advierten los investigadores de un estudio publicado en Science. Sin embargo, hay tiburones de Groenlandia que probablemente hayan nacido en el siglo XVI o XVII. No hay un solo ser humano vivo anterior al siglo XX.</p><p class="ctx-fuente"><small>Tomado y adaptado de: www.pagina12.com. El tiburón más viejo del mundo vive en Groenlandia.</small></p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('2ed8b991-c22e-48c9-8d45-6dc3757e24c4', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<p><b>Un señor muy viejo con unas alas enormes</b></p><p>Al tercer día de lluvia habían matado tantos cangrejos dentro de la casa, que Pelayo tuvo que atravesar su patio anegado para tirarlos al mar, pues el niño recién nacido había pasado la noche con calenturas y se pensaba que era a causa de la pestilencia. El mundo estaba triste desde el martes. El cielo y el mar eran una misma cosa de ceniza, y las arenas de la playa, que en marzo fulguraban como polvo de lumbre, se habían convertido en un caldo de lodo y mariscos podridos. La luz era tan mansa al mediodía, que cuando Pelayo regresaba a la casa después de haber tirado los cangrejos, le costó trabajo ver qué era lo que se movía y se quejaba en el fondo del patio. Tuvo que acercarse mucho para descubrir que era un hombre viejo, que estaba tumbado boca abajo en el lodazal, y a pesar de sus grandes esfuerzos no podía levantarse, porque se lo impedían sus enormes alas.</p><p>Asustado por aquella pesadilla, Pelayo corrió en busca de Elisenda, su mujer, que estaba poniéndole compresas al niño enfermo, y la llevó hasta el fondo del patio. Ambos observaron el cuerpo caído con un callado estupor. Estaba vestido como un trapero. Le quedaban apenas unas hilachas descoloridas en el cráneo pelado y muy pocos dientes en la boca, y su lastimosa condición de bisabuelo ensopado lo había desprovisto de toda grandeza. Sus alas de gallinazo grande, sucias y medio desplumadas, estaban encalladas para siempre en el lodazal. Tanto lo observaron, y con tanta atención, que Pelayo y Elisenda se sobrepusieron muy pronto del asombro y acabaron por encontrarlo familiar. Entonces se atrevieron a hablarle, y él les contestó en un dialecto incomprensible pero con una buena voz de navegante. Fue así como pasaron por alto el inconveniente de las alas, y concluyeron con muy buen juicio que era un náufrago solitario de alguna nave extranjera abatida por el temporal. Sin embargo, llamaron para que lo viera a una vecina que sabía todas las cosas de la vida y la muerte. A ella le bastó con una mirada para sacarlos del error.</p><p>—Es un ángel —les dijo—. Seguro que venía por el niño, pero el pobre está tan viejo que lo ha tumbado la lluvia.</p><p>Al día siguiente, todo el mundo sabía que en casa de Pelayo tenían cautivo un ángel de carne y hueso. Contra el criterio de la vecina sabia, para quien los ángeles de estos tiempos eran sobrevivientes fugitivos de una conspiración celestial, no habían tenido corazón para matarlo a palos. Pelayo estuvo vigilándolo toda la tarde desde la cocina, armado con un garrote de alguacil, y antes de acostarse lo sacó a rastras del lodazal y lo encerró con las gallinas en el gallinero alumbrado. A medianoche, cuando terminó la lluvia, Pelayo y Elisenda seguían matando cangrejos.<br>Poco después, el niño despertó sin fiebre y con deseos de comer.</p><p class="ctx-fuente"><small>Tomado de: Gabriel García Márquez. Un señor muy viejo con unas alas enormes. En La increíble historia de la Cándida Eréndira y su abuela desalmada. Bogotá: Oveja Negra, 1972.</small></p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('a5c7ccd9-a747-4c7e-89e1-338574d4a2a7', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<p><b>La muerte de Iván Ilich</b></p><p>La vida de Iván Ilich era una historia que no podía ser más vulgar y corriente, y más horrible.</p><p>Iván Ilich, muerto a los cuarenta y cinco años como miembro de la Cámara Judicial, era hijo de un funcionario que había hecho en Petersburgo, en distintos ministerios y departamentos, la carrera que lleva a los hombres a una situación en que, a pesar de mostrar su completa incapacidad para ejercer unas funciones realmente útiles, atendido su puesto en el escalafón y sus dignidades, no pueden ser despedidos, y por eso, ocupan cargos imaginarios y ficticios, por lo que gozan de unos sueldos no ficticios entre los seis mil y los ocho mil rublos, con los que viven hasta la vejez más avanzada.</p><p>Así era Iliá Efimovich Golovín, consejero secreto y miembro innecesario de diversas e innecesarias instituciones.</p><p>Había tenido tres hijos varones. Iván Ilich era el segundo. El primogénito había hecho la misma carrera que el padre, aunque en otro ministerio, y se acercaba a la edad, dentro del escalafón, en que da comienzo esta inercia de los sueldos. El hijo tercero era un fracasado. Siempre, en diversos puestos, había quedado muy mal, y ahora prestaba servicio en los ferrocarriles; lo mismo el padre que los hermanos, y particularmente las esposas de estos, se resistían a verse con él; es más, salvo una necesidad extrema, ni siquiera se acordaban de su existencia. [...] Iván Ilich era, según decían, le phoenix de la famille [el fénix de la familia]. No era tan frío y cumplidor como el mayor ni tan alocado como el menor. Ocupaba un término medio: era un hombre inteligente, vivo, agradable y decoroso. Había estudiado con el hermano menor, en la Escuela de Jurisprudencia. El menor no llegó a acabar los estudios, siendo expulsado en el quinto curso; Iván Ilich, en cambio, acabó con aprovechamiento. En la Escuela, era ya lo que había de ser toda su vida: una persona capaz, alegre, bondadosa y comunicativa, pero que cumplía rígidamente lo que consideraba su deber; y un deber era para él cuanto se consideraba como tal por los hombres más encumbrados. No fue adulador ni de chico ni luego, de adulto, pero desde sus años mozos se sintió atraído, como la mosca hacia la luz, por las personas encumbradas en la sociedad; hacía suyas sus maneras y conceptos de la vida y entablaba con ellos relaciones amistosas. Todas las pasiones de la infancia y la juventud pasaron por él sin dejar grandes huellas; se entregó también a los placeres sensuales, a la vanidad y —ya al final, en los últimos cursos— al liberalismo, pero todo dentro de ciertos límites que le señalaba fielmente su sentimiento de la medida.</p><p>Durante su estancia en la Escuela de Jurisprudencia, hizo cosas que en un principio se le figuraban verdaderas porquerías y le producían asco hacia sí mismo en el momento de realizarlas; pero más tarde, [...] no es que las considerase buenas, pero las olvidó por completo, sin que su recuerdo le produjese la menor aflicción.</p><p class="ctx-fuente"><small>Tomado de: Tolstoi, L. (1969). La muerte de Iván Ilich. Trad. José Laín Entralgo. Madrid: Salvat.</small></p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('cfe9b056-8622-4ad7-9b84-16414d9657e9', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<p>Pero luego, Tomás atravesó la frontera checa y se topó con una columna de tanques soviéticos. Tuvo que detener el coche en un cruce de caminos y esperar a que pasaran. Un horrible soldado dirigía el tráfico en el cruce, como si todas las carreteras checas fueran de su propiedad. «Debe ser así», repetía Tomás, pero pronto empezó a dudarlo: ¿de verdad tenía que ser así? Sí, era insoportable permanecer en Zúrich e imaginarse a Teresa viviendo sola. ¿Pero cuánto tiempo le torturaría la compasión? ¿Toda la vida? ¿O todo un año? ¿Cómo podía saberlo? ¿Cómo comprobarlo? Cualquier colegial puede hacer experimentos durante la clase de física y comprobar si determinada hipótesis científica es cierta. Pero el hombre, dado que vive solo una vida, nunca tiene la posibilidad de comprobar una hipótesis mediante un experimento y por eso nunca llega a averiguar si debía haber prestado oído a su sentimiento o no.</p><p>Con estos pensamientos abrió la puerta de la casa. Karenin, el perro de Teresa, le saltó a la cara y le hizo así más fácil el momento del encuentro. Las ganas de abrazar a Teresa habían desaparecido por completo. Le parecía que estaban en medio de una planicie nevada y que ambos temblaban de frío. Desde el primer día de la ocupación, los aviones rusos volaban durante toda la noche sobre Praga. Tomás se había desacostumbrado a aquel ruido y no podía dormir. Daba vueltas en la cama, mientras Teresa dormía y se acordaba de lo que había dicho hacía tiempo en una conversación intrascendente. Estaban hablando de su amigo Z. y ella afirmó: «si no te hubiera encontrado a ti, seguro que me hubiera enamorado de él».</p><p>Ya en esa ocasión, aquellas palabras le produjeron a Tomás una extraña melancolía. Y es que de pronto se dio cuenta de que era una mera casualidad el que Teresa lo amase a él y no a su amigo Z. Se dio cuenta de que, además del amor de ella por Tomás, hecho realidad, existe en el reino de lo posible una cantidad infinita de amores no realizados por otros hombres. Tomás se acordaba del comentario de Teresa sobre el amigo Z. y constataba que la historia del amor de su vida no iba acompañada de ningún «¡Debe ser así!», sino que también podía haber sido de otro modo.</p><p>Hace siete años se produjo, casualmente en el hospital de la ciudad de Teresa, un complicado caso, a causa del cual llamaron con urgencia al director del hospital de Tomás. Pero el director tenía casualmente una ciática, y envió en su lugar a Tomás. En la ciudad había cinco hoteles, pero Tomás fue a parar casualmente justo a aquel donde trabajaba Teresa. Casualmente le sobró un poco de tiempo para ir al restaurante antes de la salida del tren. Teresa casualmente estaba de servicio y casualmente atendió la mesa de Tomás. Hizo falta que se produjeran seis casualidades para empujar a Tomás hacia Teresa, como si él mismo no tuviera ganas.</p><p class="ctx-fuente"><small>Tomado y adaptado de: Kundera, M. (2002). La insoportable levedad del ser. México: Tusquets Editores S. A.</small></p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('66bb3ca2-b0b4-45e9-b0b8-4837aa4eb278', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<p>En el Líbano, como en otros países del Medio Oriente, el centro de Asia, el subcontinente indio y el norte de Europa, la leche ha sido por milenios un alimento esencial y necesario. Por esto, su gente ha desarrollado mutaciones genéticas para poder digerir la lactosa aun después de la infancia. En otras regiones, como América, el grueso de la población suele volverse intolerante a la lactosa luego de cumplir los cinco o seis años, pues se supone que el ser humano es destetado apenas es capaz de comer alimentos sólidos. ¿Por qué el cuerpo seguiría desgastándose en la producción de la enzima encargada de digerir ese azúcar que se encuentra en un solo alimento de la naturaleza? Tomar la leche de otros mamíferos es una aberración cultural humana. En América no se consumía antes de la llegada de los españoles; en China, la dinastía Ming desterró el consumo de leche al mismo tiempo que borraba de su historia a los mongoles que la precedieron y sus costumbres bárbaras, como tomar kumis. Hubo incluso un cortesano que se refirió al queso como «una mucosa secreción de las tripas de una vieja vaca, que luego se deja podrir».</p><p class="ctx-fuente"><small>Tomado y adaptado de: Ganem Maloof, K. En El Malpensante, edición 206. Bogotá D. C.</small></p>');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '7635658d-08a2-4668-b9fd-1df9725c3db4', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'tesis-y-argumentos'),
  (select id from public.lotes where codigo = '2026-B'),
  'f2998627-1c88-4ed3-a2f4-cfd1bd5e0575', 'Tesis y argumentos',
  '¿Cuál de las siguientes afirmaciones defiende la autora en el texto?',
  array['Nos planteamos las mismas preguntas para hombres y mujeres que tienen posiciones de poder.', 'Las mujeres poderosas son vigiladas, porque la sociedad nos ha hecho creer que no deben tener posiciones de poder.', 'La permisividad masculina es un factor necesario para la defensa de la igualdad entre hombres y mujeres.', 'A las personas que cuestionan a las mujeres poderosas les desagrada el poder en sí mismo y no las mujeres.'],
  'Busca cómo explica la autora el trato distinto hacia mujeres y hombres con poder.', 'publicada', 'modelo', '6d688d32b3194f1d5371a8372bb59396', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('7635658d-08a2-4668-b9fd-1df9725c3db4', 1, 'La autora vincula la vigilancia de las mujeres poderosas con el aprendizaje social de que el poder es masculino. Las otras afirmaciones invierten su crítica a la desigualdad y al lenguaje de permiso.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'f97c3908-43df-46a4-8381-a52dd4b67287', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'inferencia'),
  (select id from public.lotes where codigo = '2026-B'),
  'f2998627-1c88-4ed3-a2f4-cfd1bd5e0575', 'Inferencia',
  'Considere el siguiente enunciado: «El bienestar de una mujer debe basarse en algo más que la benevolencia masculina». ¿Cuál de las siguientes opciones expresa una idea afín al anterior enunciado?',
  array['El bienestar de las mujeres no depende de que los hombres decidan tratarlas como benévolas.', 'Las buenas acciones de los hombres no son suficientes para garantizar el bienestar de la mujer.', 'El bienestar de las mujeres depende de que los hombres agradezcan las acciones de las mujeres.', 'Las buenas actitudes de los hombres son indispensables para garantizar el bienestar de la mujer.'],
  'Conserva el sentido de insuficiencia expresado por «algo más».', 'publicada', 'modelo', '7bb35c94e4c5636400d1b7b3e0f03560', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('f97c3908-43df-46a4-8381-a52dd4b67287', 1, '«Algo más» indica que la buena voluntad masculina no basta como fundamento. No afirma que las mujeres deban ser tratadas como benévolas ni que dependan del agradecimiento de los hombres.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'd5cbc8dc-2847-4b3c-aac9-e34d1684bc17', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'evaluacion-critica'),
  (select id from public.lotes where codigo = '2026-B'),
  '9cb858cb-291c-492c-b32a-f6270f022925', 'Evaluación crítica',
  'Considere el siguiente fragmento: «A lo largo de la accidentada primera noche que el náufrago pasó a la deriva en el mar, el hambre, sed, la fatiga y la soledad casi hicieron que perdiera la razón: la acumulación de circunstancias adversas contribuyó a que su mente concibiera extrañas alucinaciones». El resumen anterior es',
  array['inexacto, pues los hechos descritos en el resumen no transcurren durante el primer día.', 'premonitorio, pues nos anticipa que el náufrago sufrirá alucinaciones posteriormente.', 'exagerado, pues el náufrago afirma que no tenía hambre, sino que tenía mucha sed.', 'sentimental, puesto que describe las sensaciones que el personaje tiene en su vida.'],
  'Usa la referencia temporal de la última oración.', 'publicada', 'modelo', 'bb9b6c70426293fe5a0d78c464880666', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('d5cbc8dc-2847-4b3c-aac9-e34d1684bc17', 0, 'El final ubica el amanecer en el tercer día de soledad, por lo que llamar a la noche narrada «primera noche» altera la cronología. La opción disponible habla de primer día, con imprecisión, pero es la que detecta ese error temporal. El hambre sí aparece más adelante en el relato.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '3f641b1f-87d7-4368-b426-180b16fdd26d', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'informacion-literal'),
  (select id from public.lotes where codigo = '2026-B'),
  '144cd6d7-a0c6-437d-99eb-179ffded760e', 'Información literal',
  'En el texto, la serpiente intervino luego de que lo hicieran el',
  array['cuervo y el palomo.', 'cuervo y el ciervo.', 'palomo y el ermitaño.', 'palomo y el ciervo.'],
  'Sigue el orden de las intervenciones.', 'publicada', 'modelo', 'a2da7d0c1e625a119346705e441d5ff9', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('3f641b1f-87d7-4368-b426-180b16fdd26d', 0, 'Primero habla el cuervo sobre el hambre y después el palomo sobre el amor. La serpiente retoma y rechaza ambas propuestas antes de hablar de la ira.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '10c5a0fe-25d7-4763-b93e-60db7218b3b2', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'tesis-y-argumentos'),
  (select id from public.lotes where codigo = '2026-B'),
  '144cd6d7-a0c6-437d-99eb-179ffded760e', 'Tesis y argumentos',
  'Un enunciado que expresa una opinión similar a la del ermitaño es',
  array['el hambre, el amor, la ira y el miedo son el origen de todos los males.', 'los males que sufrimos dependen de nuestra historia personal.', 'solamente la experiencia permite conocer el origen del mal.', 'el mal es propio de la condición humana.'],
  'Distingue la causa general que propone de las causas parciales de los animales.', 'publicada', 'modelo', '2db8d3d40d8a1e3a49f87ef65ff9fb20', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('10c5a0fe-25d7-4763-b93e-60db7218b3b2', 3, 'El ermitaño sitúa la fuente en la propia naturaleza, de la que surgen hambre, amor, ira y miedo. No limita la explicación a uno de esos estados ni a una biografía particular.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'd6783bc6-b9aa-4ec0-8418-9e934c072e50', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'proposito-del-texto'),
  (select id from public.lotes where codigo = '2026-B'),
  '144cd6d7-a0c6-437d-99eb-179ffded760e', 'Propósito del texto',
  'En el texto anterior, los personajes',
  array['debaten las consecuencias de guiarse por las emociones.', 'discuten sobre nuestra naturaleza.', 'explican el origen del amor, la ira, el hambre y el miedo.', 'proponen hipótesis sobre la fuente del mal.'],
  'Vuelve a la pregunta que inicia la discusión.', 'publicada', 'modelo', 'a878fcce41e6d192f86e37de2419b671', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('d6783bc6-b9aa-4ec0-8418-9e934c072e50', 3, 'Cada personaje propone un origen del mal y trata de justificarlo. La naturaleza aparece como la respuesta final del ermitaño, no como el tema explícito de todas las intervenciones.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '4ca42aad-36b2-4fe3-a99c-6649f9c6872f', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'inferencia'),
  (select id from public.lotes where codigo = '2026-B'),
  '144cd6d7-a0c6-437d-99eb-179ffded760e', 'Inferencia',
  'Con la expresión «En tales momentos no se tiene piedad de nadie; mordería uno a su propia madre, podríamos comernos a nosotros mismos», la serpiente afirma que la ira es',
  array['un acto perjudicial para cualquiera.', 'un sentimiento que deriva en la muerte.', 'una necesidad de daño autoinfligido.', 'una emoción que no mide consecuencias.'],
  'Busca la idea común al daño contra otros y contra uno mismo.', 'publicada', 'modelo', 'e2d9cd9f0cf8abf464a22002eda9a115', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4ca42aad-36b2-4fe3-a99c-6649f9c6872f', 3, 'Los ejemplos muestran una reacción que no se detiene ante el daño a otros ni a sí mismo. No afirman que toda ira termine en muerte ni que sea una necesidad de autolesión.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '46c58c89-e914-46a9-9007-bad3c8363d0e', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'textos-discontinuos'),
  (select id from public.lotes where codigo = '2026-B'),
  'cf940cce-9c38-483b-8579-c491da3e2ca4', 'Textos discontinuos',
  'De acuerdo con la infografía, en cuarenta años de conflicto el mayor número de secuestros fue perpetrado por',
  array['grupos paramilitares.', 'delincuencia común.', 'grupos guerrilleros.', 'no combatientes.'],
  'Compara las cifras de secuestros, no las de muertes.', 'publicada', 'modelo', '49b58ccfefc6d00ac43b70f1a2c1827f', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('46c58c89-e914-46a9-9007-bad3c8363d0e', 2, 'La gráfica atribuye 24.482 secuestros a guerrillas y 2.541 a grupos paramilitares. El primer valor es mayor.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '747f689c-bbd4-4e2f-984b-5a77349cc441', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'textos-discontinuos'),
  (select id from public.lotes where codigo = '2026-B'),
  'cf940cce-9c38-483b-8579-c491da3e2ca4', 'Textos discontinuos',
  'De acuerdo con la infografía, se puede afirmar que',
  array['en el sur del país hay menos municipios afectados por el conflicto armado.', 'en el norte del país hay menos municipios afectados por el conflicto armado.', 'en el sur del país hay más municipios afectados por el secuestro.', 'en el norte del país hay más municipios afectados por el secuestro.'],
  'Identifica qué fenómeno representa el mapa antes de comparar norte y sur.', 'publicada', 'modelo', 'ba9ede8e448b860671dd035799b0b954', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('747f689c-bbd4-4e2f-984b-5a77349cc441', 3, 'En el mapa de municipios críticos por secuestro se concentra un mayor número de puntos hacia el norte. La afirmación se refiere a ese mapa, no a todos los municipios afectados por cualquier forma del conflicto.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'cf921da6-581a-4fb3-b564-8a532bf4544b', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'punto-de-vista'),
  (select id from public.lotes where codigo = '2026-B'),
  'db8b8e5a-c752-436c-bc83-b091c434c17e', 'Punto de vista del autor',
  'En el segundo párrafo del texto, la expresión «¡Qué horrible!» representa',
  array['la perspectiva del autor.', 'el punto de vista del futbolista.', 'una perspectiva común en los televidentes.', 'el punto de vista de todos los colombianos.'],
  'Contrasta la exclamación con «Nada más bello que un hombre llorando».', 'publicada', 'modelo', '3c4babf51ef8dcd33a418192305970c7', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('cf921da6-581a-4fb3-b564-8a532bf4544b', 2, 'El autor reproduce irónicamente el rechazo social al llanto masculino para criticarlo después. Su postura explícita es favorable al llanto, por lo que la exclamación dramatiza una reacción común, sin atribuirla a todos los colombianos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '98f51a9b-3e71-4ae3-a0b8-dabbdfa44b1b', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'tesis-y-argumentos'),
  (select id from public.lotes where codigo = '2026-B'),
  'db8b8e5a-c752-436c-bc83-b091c434c17e', 'Tesis y argumentos',
  '¿Cuál de las siguientes afirmaciones representa la tesis del texto?',
  array['El llanto de los hombres debe valorarse positivamente.', 'El llanto es la expresión de las emociones más profundas.', 'Los hombres se han educado para no expresar sus sentimientos.', 'Los hombres deben llorar para demostrar sus sentimientos.'],
  'Distingue la postura central de las razones y del problema que la motiva.', 'publicada', 'modelo', '8959f682cde7ad3f867f12e3527ea8d7', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('98f51a9b-3e71-4ae3-a0b8-dabbdfa44b1b', 0, 'La conclusión elogia a quien llora pese a la prohibición cultural. La educación represiva es el problema criticado y la expresión emocional es una razón para valorar el llanto, no una obligación de demostrar sentimientos llorando.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '7c87caad-2cbf-4266-8105-8e13e5a4ee94', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'evaluacion-critica'),
  (select id from public.lotes where codigo = '2026-B'),
  'db8b8e5a-c752-436c-bc83-b091c434c17e', 'Evaluación crítica',
  '¿Qué comportamiento social sanciona el texto?',
  array['La incapacidad de los hombres de expresarles afecto a las mujeres.', 'La expresión de ternura es aceptable únicamente en las mujeres.', 'La carencia de sentimientos y ternura en los hombres machistas.', 'La rudeza y agresividad propia del comportamiento masculino.'],
  'Busca la prohibición cultural, no una supuesta incapacidad natural.', 'publicada', 'modelo', '09d1cb86cc20ed78571393134433a6a9', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('7c87caad-2cbf-4266-8105-8e13e5a4ee94', 1, 'El blanco de la crítica es la norma social que permite sensibilidad a las mujeres y se la prohíbe a los hombres. El autor no sostiene que los hombres carezcan realmente de sentimientos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '40db5d31-1bc7-47c3-b244-c06824c6e78f', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'proposito-del-texto'),
  (select id from public.lotes where codigo = '2026-B'),
  'bcdbf032-a8f9-4d07-a24b-bdb85c0a7566', 'Propósito del texto',
  'La pregunta central a la que responde el texto es:',
  array['¿Cuántas personas sufrirán hambrunas en 2020?', '¿Cómo afecta la pandemia a ricos y a pobres?', '¿Por qué la pandemia afecta más ricos que a pobres?', '¿Por qué el mendigo dijo que no necesitaba nada?'],
  'Relaciona el encuentro inicial con la reflexión final.', 'publicada', 'modelo', '6ee7b475280f1d2fe74525ec839cf59a', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('40db5d31-1bc7-47c3-b244-c06824c6e78f', 1, 'La comparación entre la narradora que puede comprar y el hombre que vive en la calle cuestiona la idea de que la pandemia afecta a todos por igual. Las cifras apoyan esa desigualdad.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '44d71211-6bba-42ca-b259-deff9f68b356', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'estructura-textual'),
  (select id from public.lotes where codigo = '2026-B'),
  'bcdbf032-a8f9-4d07-a24b-bdb85c0a7566', 'Estructura y articulación del texto',
  'Teniendo en cuenta su estructura, tono y estilo, ¿en qué tipo de publicación podría aparecer el texto?',
  array['En un libro de historia sobre los impactos sociales y económicos de la pandemia.', 'En la sección de opinión de un periódico o revista.', 'En una pieza publicitaria que promociona una nueva tarjeta de crédito.', 'En la sección de noticias de un medio de comunicación.'],
  'Observa cuánto peso tienen la experiencia y la valoración de la narradora.', 'publicada', 'modelo', '50cbdd0913522911e2b84f12053c360c', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('44d71211-6bba-42ca-b259-deff9f68b356', 1, 'Combina una experiencia personal, datos y una valoración crítica expresada en primera persona. Esa estructura corresponde a una columna de opinión.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'b89d0b03-7fbc-4845-8c40-81a3ac8249d9', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'estructura-textual'),
  (select id from public.lotes where codigo = '2026-B'),
  'bcdbf032-a8f9-4d07-a24b-bdb85c0a7566', 'Estructura y articulación del texto',
  'La narradora del texto es',
  array['una testigo, porque a pesar de que el texto está narrado en primera persona, es objetivo en sus observaciones y nos cuenta la historia con pocas referencias a sí misma.', 'omnisciente, porque conoce todo lo que pasa, desde los millones de personas que están muriendo de hambre hasta los pensamientos más íntimos del mendigo.', 'la protagonista, porque se sitúa a sí misma en el centro de la acción, habla en primera persona y cuenta los hechos desde su propio punto de vista subjetivo.', 'observadora porque hace una descripción de los hechos en segunda persona, con un conocimiento limitado a lo que puede percibir de un personaje.'],
  'Identifica quién realiza las acciones y expresa los juicios.', 'publicada', 'modelo', '87f7910252f21469a2ee9e9eb5152629', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('b89d0b03-7fbc-4845-8c40-81a3ac8249d9', 2, 'Cuenta su salida, el encuentro y su propia reacción; además reconoce lo que desconoce del hombre. Habla en primera persona desde una perspectiva subjetiva.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'fd0ead1c-8d1c-4a78-a6af-d30328a42207', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'tesis-y-argumentos'),
  (select id from public.lotes where codigo = '2026-B'),
  'bcdbf032-a8f9-4d07-a24b-bdb85c0a7566', 'Tesis y argumentos',
  'Considere los siguientes enunciados del texto. Enunciado 1: «Esta pandemia demuestra que el virus no discrimina». Enunciado 2: «El nuevo mendigo no ha vuelto a aparecer. Yo sigo haciendo mis compras. Con tarjeta de crédito». ¿Cuál es la relación entre los enunciados 1 y 2?',
  array['2 es una razón a favor de lo dicho en 1.', '1 es una conclusión que se sigue de lo dicho.', '2 presenta una razón en contra de lo dicho.', '1 presenta una afirmación similar a lo dicho.'],
  'Fíjate en la pregunta «¿No discrimina?» que enlaza las dos ideas.', 'publicada', 'modelo', '278a54e09217906aee0343f9eccaa065', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('fd0ead1c-8d1c-4a78-a6af-d30328a42207', 2, 'El contraste de situaciones sirve para cuestionar la afirmación de igualdad de efectos. No respalda que todos afronten las mismas consecuencias sociales y económicas.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'ca3e2608-b792-400e-9821-582ce5ba8a6d', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'estructura-textual'),
  (select id from public.lotes where codigo = '2026-B'),
  '8f87e14e-20e5-4ace-a7cc-21b7c243067e', 'Estructura y articulación del texto',
  'El narrador en el texto',
  array['es omnisciente, lo sabe todo y narra en tercera persona.', 'utiliza la primera persona, a pesar de que emplea el plural.', 'la segunda persona, pues se refiere a nosotros sin incluirse.', 'no lo sabe todo y narra lo que acontece en la tercera persona.'],
  'Observa los pronombres y las formas verbales.', 'publicada', 'modelo', '33d34ac9556bc64c66143c260045cf89', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('ca3e2608-b792-400e-9821-582ce5ba8a6d', 1, 'Las formas «nuestra», «asociamos» e «invocamos» incluyen al narrador en un nosotros. Son marcas de primera persona plural.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'b1d8c536-b2bc-4914-a89f-7995de6e1c22', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'tesis-y-argumentos'),
  (select id from public.lotes where codigo = '2026-B'),
  '8f87e14e-20e5-4ace-a7cc-21b7c243067e', 'Tesis y argumentos',
  'Considere los siguientes dos enunciados del texto: 1. «Es ese espejismo de dominio sobre nuestra propia vida lo que nos permite sentirnos adultos». 2. «Asociamos la adultez con la autonomía, el soberano derecho a determinar lo que va a sucedernos enseguida». ¿Cuál es la relación argumentativa entre 1 y 2?',
  array['1 es una razón a favor de 2.', '2 es una razón a favor de 1.', '2 es una razón en contra de 1.', '1 es una razón en contra de 2.'],
  'Identifica qué enunciado responde por qué ocurre lo afirmado en el otro.', 'publicada', 'modelo', 'dda2fc125eb0c195a78dc69d70be0843', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('b1d8c536-b2bc-4914-a89f-7995de6e1c22', 1, 'La asociación de adultez con autonomía explica por qué la ilusión de controlar la vida nos hace sentir adultos. El conector «pues» introduce esa justificación.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '82739bd3-1fb8-4f49-9de4-96773980a69e', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'punto-de-vista'),
  (select id from public.lotes where codigo = '2026-B'),
  '8f87e14e-20e5-4ace-a7cc-21b7c243067e', 'Punto de vista del autor',
  'En el texto, el autor juzga como algo cuestionable a',
  array['la autonomía.', 'la edad adulta.', 'la ilusión de control.', 'el poco control que tenemos.'],
  'Busca las palabras con valoración negativa.', 'publicada', 'modelo', '489234c510d297b4a75ebdfad7db61d1', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('82739bd3-1fb8-4f49-9de4-96773980a69e', 2, 'La llama «ilusión perniciosa» y «espejismo», y luego muestra hechos que la desmienten. No condena la edad adulta en sí.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'a2dc307d-c68a-464c-8e20-3c3b37346a55', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'inferencia'),
  (select id from public.lotes where codigo = '2026-B'),
  '8f87e14e-20e5-4ace-a7cc-21b7c243067e', 'Inferencia',
  'De acuerdo con el texto, ¿en qué momento nos damos cuenta del poco control que tenemos sobre nuestra vida?',
  array['Cuando la ilusión de control que tienen los adultos se hace patente.', 'Cuando nos damos cuenta de que nuestra vida ha sido moldeada por eventos ajenos a nuestra voluntad.', 'Cuando nuestros planes más espléndidos triunfan ante eventos inesperados.', 'Cuando otra persona nos muestra cómo nuestra voluntad es responsable de los procesos que se topan con nuestra vida.'],
  'Relaciona el desengaño con las causas que han moldeado la biografía.', 'publicada', 'modelo', '9610693c4aeaf1ac6bf6eb602bcbd17d', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('a2dc307d-c68a-464c-8e20-3c3b37346a55', 1, 'El desengaño aparece al reconocer que sucesos lejanos y voluntades ajenas han configurado nuestra biografía. Eso contradice la idea de dominio completo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '7ac0d0f1-3f42-4b90-9c5a-cef027df331c', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'estructura-textual'),
  (select id from public.lotes where codigo = '2026-B'),
  '8f87e14e-20e5-4ace-a7cc-21b7c243067e', 'Estructura y articulación del texto',
  'El texto anterior probablemente hace parte de una obra de carácter',
  array['académico, como un artículo científico.', 'publicitario, como un anuncio.', 'artístico, como una novela.', 'periodístico, como una entrevista.'],
  'Considera el lenguaje figurado y la forma de la voz narrativa.', 'publicada', 'modelo', 'e356fee63ce383a0973d02a76f0e870c', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('7ac0d0f1-3f42-4b90-9c5a-cef027df331c', 2, 'El pasaje desarrolla una reflexión mediante una voz narrativa y comparaciones literarias. No presenta metodología científica, preguntas y respuestas de entrevista ni promoción de un producto.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'f69eda29-2b95-4928-b17a-5c98bec2e183', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'evaluacion-critica'),
  (select id from public.lotes where codigo = '2026-B'),
  '43e632cc-0850-4ff9-b5fb-948bd838da7c', 'Evaluación crítica',
  '¿Cuál de los siguientes enunciados contradice la idea de que «La única obligación a la que debo someterme es a la de hacer siempre lo que creo correcto»?',
  array['No todos los individuos actúan de forma correcta, lo cual puede derivar en actos de injusticia.', 'Lo correcto tiene un carácter subjetivo, por tanto, no está menos sujeto a la arbitrariedad que la ley.', 'La ley siempre refleja la voluntad de la mayoría y, por tanto, lo correcto es someterse a ella.', 'No son los individuos quienes deben definir lo que es correcto, sino los gobiernos a los cuales se someten.'],
  'Distingue una objeción a una tesis de su contradicción directa.', 'borrador', 'modelo', '92ecf89213b157f89fad966aed813fbc', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('f69eda29-2b95-4928-b17a-5c98bec2e183', 3, 'Pregunta en borrador: tanto someter lo correcto a la ley como reservar su definición al gobierno se oponen a la primacía de la conciencia individual del enunciado. El material no permite una clave única suficientemente justificada entre esas dos opciones.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '701e7870-5b3c-4320-8311-6ba467bd748f', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'semantica-y-lexico'),
  (select id from public.lotes where codigo = '2026-B'),
  'a58f6f34-d6f2-47fe-a98c-58068a6e78ac', 'Semántica y léxico',
  'En el primer párrafo, el autor menciona «un pequeño arroyo escarlata», para referirse a',
  array['la apariencia que tomaría la calle después de que el capitán Torres fuera asesinado.', 'un golpe rápido que necesitaría el narrador para convertirse en un verdadero asesino.', 'la sangre derramándose por el piso si el narrador llegara a asesinar al capitán Torres.', 'un caudal de agua que corre cerca de la calle del lugar donde vive el asesino de la historia.'],
  'Lee qué sustancia describe la oración inmediatamente anterior.', 'publicada', 'modelo', '0c0ae62896510883b91b25d999f45b7d', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('701e7870-5b3c-4320-8311-6ba467bd748f', 2, 'El narrador imagina sangre corriendo por el piso hasta la calle y la compara con un arroyo rojo. La muerte es una posibilidad que considera, no un hecho consumado.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '9e67ee12-2f35-468f-b377-37f27bc45e2e', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'evaluacion-critica'),
  (select id from public.lotes where codigo = '2026-B'),
  'a58f6f34-d6f2-47fe-a98c-58068a6e78ac', 'Evaluación crítica',
  'Considere el siguiente resumen: «La historia trata acerca del barbero de un pueblo que, como parte de un plan para convertirse en héroe, lleva al capitán Torres a su casa para arreglarle la barba y así tener la oportunidad de asesinarlo en favor de los revolucionarios, aunque el capitán accede, la cobardía del barbero y su falta de compromiso con la revolución le impiden llevar a cabo su plan. Luego de examinar los pros y contras que implican el asesinato, el barbero decide, finalmente, dejar con vida al capitán, quien le asegura que lo ha defraudado porque esperaba que él lo asesinara, como le habían dicho que lo haría». El resumen anterior puede considerarse',
  array['inadecuado, porque tergiversa elementos de la historia e introduce otros que no están presentes.', 'adecuado, pues resalta los detalles más importantes de la narración de una manera correcta.', 'inadecuado, porque omite el estilo propio del autor que le imprime un sello particular a la historia.', 'adecuado, pues une los hechos del texto de una manera articulada y en el orden en que ocurrieron.'],
  'Comprueba qué hechos y motivos añade el resumen sin apoyo en el relato.', 'publicada', 'modelo', '43c16ff40ddf2af0ad0295b39cd2fc7b', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('9e67ee12-2f35-468f-b377-37f27bc45e2e', 0, 'El fragmento no dice que el barbero llevara a Torres mediante un plan ni que este se sintiera defraudado. También reduce a cobardía un conflicto moral expresado como rechazo a convertirse en asesino.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'd7ade1ed-62b4-4e32-962a-340edb1e749f', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'estructura-textual'),
  (select id from public.lotes where codigo = '2026-B'),
  'a58f6f34-d6f2-47fe-a98c-58068a6e78ac', 'Estructura y articulación del texto',
  'Al final del primer párrafo, unos puntos suspensivos entre corchetes indican un fragmento del texto original que no se ha incluido en esta adaptación. ¿Cuál de las siguientes opciones es la continuación más coherente y adecuada para completar ese párrafo?',
  array['«La navaja seguía descendiendo. Ahora de la otra patilla hacia abajo. Una barba azul, cerrada. Debía dejársela crecer como algunos poetas o como algunos sacerdotes. Le quedaría bien. Muchos no lo reconocerían. Y mejor para él, pensé, mientras trataba de pulir suavemente todo el sector del cuello».', '«Del filo de esta navaja depende mi destino. Puedo inclinar un poco más la mano, apoyar un poco más la hoja, y hundirla. La piel cederá como la seda, como el caucho, como la badana. No hay nada más tierno que la piel del hombre y la sangre siempre está ahí, lista a brotar. Una navaja como esta no traiciona. Es la mejor de mis navajas».', '«Probablemente muchos de los nuestros lo habrían visto entrar. Y el enemigo en la casa impone condiciones. Yo tendría que afeitar esa barba como cualquiera otra, con cuidado, con esmero, como la de un buen parroquiano, cuidando de que ni por un solo poro fuese a brotar una gota de sangre».', '«El día en que ordenó que el pueblo desfilara por el patio de la escuela para ver a los cuatro rebeldes allí colgados, me crucé con él un instante. Pero el espectáculo de los cuerpos mutilados me impedía fijarme en el rostro del hombre que los había dirigido y que ahora iba a tomar mis manos. No era un rostro desagradable, ciertamente».'],
  'Conecta la pregunta previa al corte con la decisión posterior.', 'publicada', 'modelo', 'ba778bc8453dfdd3ca7fcc3982075771', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('d7ade1ed-62b4-4e32-962a-340edb1e749f', 1, 'Después de preguntarse si sería asesino o héroe, la reflexión sobre la navaja de la que depende su destino mantiene el dilema inmediato. Además enlaza con la decisión siguiente de no convertirse en asesino.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '33937cfc-ff06-4eca-8a0d-df48898d98ed', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'estructura-textual'),
  (select id from public.lotes where codigo = '2026-B'),
  'd8ccd6ef-aad0-45c9-a846-368aa2803e83', 'Estructura y articulación del texto',
  'Considere el siguiente resumen del tercer párrafo: «El tiburón de Groenlandia es uno de los animales más grandes del mundo que se alimenta de otros animales. No obstante, tiene una tasa de crecimiento extremadamente lenta». ¿Cuál de los siguientes enunciados sería necesario para complementar el resumen?',
  array['Por lo anterior, fue una fortuna haber encontrado un espécimen de 550 centímetros.', 'Por lo anterior, la mayor parte de especímenes miden más de cinco metros.', 'Por lo anterior, requiere más de 510 años para alcanzar un tamaño de cinco metros.', 'Por lo anterior, es una criatura con poca competencia en el reino animal.'],
  'Incluye la idea final del párrafo sin convertir una tasa aproximada en un cálculo no expuesto.', 'publicada', 'modelo', 'e31fc8c7b9d179048745b02b084d9272', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('33937cfc-ff06-4eca-8a0d-df48898d98ed', 0, 'Falta la valoración del hallazgo del ejemplar de 550 centímetros, que cierra el tercer párrafo. Las otras opciones agregan afirmaciones que ese párrafo no ofrece.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '02a7b33f-49a5-44b3-81b5-e387e0c986b2', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'inferencia'),
  (select id from public.lotes where codigo = '2026-B'),
  '2ed8b991-c22e-48c9-8d45-6dc3757e24c4', 'Inferencia',
  'Basado en la información del fragmento, se puede afirmar que Pelayo encontró al ángel un',
  array['domingo en la mañana.', 'sábado por la tarde.', 'viernes en la tarde.', 'jueves medio día.'],
  'Relaciona «tercer día de lluvia», «desde el martes» y «al mediodía».', 'publicada', 'modelo', '850904ddfa5f74ba3ff44763a9d0a916', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('02a7b33f-49a5-44b3-81b5-e387e0c986b2', 3, 'El encuentro ocurre al mediodía del tercer día de lluvia. El texto dice también que el mundo estaba triste desde el martes, lo que permite inferir jueves si se vincula ese martes con el inicio de la lluvia. Esa asociación es la que sustenta la respuesta.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '87388a9b-e0ec-4594-b544-5cefbb2053de', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'inferencia'),
  (select id from public.lotes where codigo = '2026-B'),
  '2ed8b991-c22e-48c9-8d45-6dc3757e24c4', 'Inferencia',
  'El texto sugiere que Pelayo y Elisenda atribuyen las fiebres de su niño a la pestilencia basados en',
  array['las propiedades de los cangrejos.', 'las creencias populares.', 'un dogma de fe.', 'una conjetura.'],
  'Distingue una suposición de una causa demostrada.', 'publicada', 'modelo', '95858e9374b294e765c06b2ddfbe955c', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('87388a9b-e0ec-4594-b544-5cefbb2053de', 3, 'La expresión «se pensaba que era a causa» presenta una suposición causal. El fragmento no aporta una comprobación ni la vincula con un dogma.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'd91aee54-e904-466c-b7ba-f45f2a4a8afe', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'funcion-de-expresiones'),
  (select id from public.lotes where codigo = '2026-B'),
  'a5c7ccd9-a747-4c7e-89e1-338574d4a2a7', 'Función de expresiones',
  'La frase «desde sus años mozos se sintió atraído, como la mosca hacia la luz, por las personas encumbradas en la sociedad» contiene una',
  array['personificación.', 'exageración.', 'metáfora.', 'ironía.'],
  'Busca si la semejanza se formula explícitamente con «como».', 'borrador', 'modelo', '758de6fdc6b4bde68826dd4a87b183ab', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('d91aee54-e904-466c-b7ba-f45f2a4a8afe', 2, 'Pregunta en borrador: «como la mosca hacia la luz» establece una comparación explícita, o símil. Esa figura no aparece entre las opciones. No corresponde calificarla automáticamente como metáfora por ser la alternativa más próxima.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '4e476fa8-a7a7-4f2b-8f32-7a3edfe21ff2', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'punto-de-vista'),
  (select id from public.lotes where codigo = '2026-B'),
  'a5c7ccd9-a747-4c7e-89e1-338574d4a2a7', 'Punto de vista del autor',
  '¿Quién adopta una postura crítica frente a la sociedad descrita en el texto?',
  array['Iliá Efimovich Golovín, consejero de Gobierno.', 'El fracasado hermano menor.', 'El narrador del relato.', 'El propio Iván Ilich.'],
  'Identifica quién formula los juicios sobre cargos, instituciones y costumbres.', 'publicada', 'modelo', 'e942edbbdccb84a0fad490384cb28cd0', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4e476fa8-a7a7-4f2b-8f32-7a3edfe21ff2', 2, 'La voz narrativa llama innecesarios a cargos e instituciones y contrasta empleos ficticios con sueldos reales. Los personajes descritos no enuncian esa crítica.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'f0b54460-01b5-4b17-988b-a8e3318cc99b', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'inferencia'),
  (select id from public.lotes where codigo = '2026-B'),
  'cfe9b056-8622-4ad7-9b84-16414d9657e9', 'Inferencia',
  'Considere el fragmento: «Debe ser así, repetía Tomás, pero pronto empezó a dudarlo: ¿de verdad tenía que ser así? Sí, era insoportable permanecer en Zúrich e imaginarse a Teresa viviendo sola. ¿Pero cuánto tiempo le torturaría la compasión? ¿Toda la vida? ¿O todo un año? ¿Cómo podía saberlo? ¿Cómo comprobarlo?». En el fragmento anterior, la frase «Debe ser así» es pronunciada por Tomás y va dirigida',
  array['a Teresa, para persuadirla de la sinceridad de su amor.', 'al lector, para justificar su cuestionada manera de obrar.', 'a sí mismo, para convencerse de su propio modo de proceder.', 'al narrador, para resignarse al amargo destino que le fue asignado.'],
  'Observa si hay un interlocutor presente o una reflexión interior.', 'publicada', 'modelo', '5b03da933e18855a827c62277f00e516', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('f0b54460-01b5-4b17-988b-a8e3318cc99b', 2, 'La repetición forma parte de su reflexión mientras viaja. Las dudas que siguen muestran que intenta sostener ante sí mismo su decisión de regresar.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '38c30d08-7181-47cf-9fb2-30ebdd4da089', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'informacion-literal'),
  (select id from public.lotes where codigo = '2026-B'),
  'cfe9b056-8622-4ad7-9b84-16414d9657e9', 'Información literal',
  'Motivado por su deseo de visitar a Teresa, Tomás decide ir',
  array['de Rusia a Praga, ciudad donde su amada se había radicado junto a su amigo Z.', 'de Praga al restaurante de uno de los cinco hoteles que se encuentran en Zúrich.', 'de Zúrich a una llanura fría y cubierta de nieve situada en algún punto del vasto territorio ruso.', 'de Zúrich a Praga, cuando esta última se hallaba bajo el dominio de la Unión Soviética.'],
  'Separa los lugares reales de la comparación sobre el frío.', 'publicada', 'modelo', '1e59fe7d947560f4212fe18ca5a9ae05', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('38c30d08-7181-47cf-9fb2-30ebdd4da089', 3, 'El personaje deja Zúrich, cruza la frontera checa y llega a la casa de Teresa en una Praga ocupada. La planicie nevada expresa cómo percibe el encuentro, no el destino geográfico.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '808006d0-40d4-4f1e-ad65-39a47acc2d6e', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'estructura-textual'),
  (select id from public.lotes where codigo = '2026-B'),
  'cfe9b056-8622-4ad7-9b84-16414d9657e9', 'Estructura y articulación del texto',
  'A juzgar por su forma y contenido, el texto anterior ha sido extraído de',
  array['un libro de historia de la Unión Soviética.', 'unas crónicas periodísticas del siglo XIX.', 'una novela escrita durante el siglo XX.', 'un pasaje del diario íntimo de Tomás.'],
  'Observa la voz narrativa y el tipo de acceso a los pensamientos.', 'publicada', 'modelo', '0f10b480f1c5b27a494d6d966c4fb4eb', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('808006d0-40d4-4f1e-ad65-39a47acc2d6e', 2, 'Una voz en tercera persona narra acciones y pensamientos íntimos de los personajes dentro de una historia. La presencia de la ocupación soviética también descarta situarlo en el siglo XIX.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '55586e49-e730-4fcc-8a2c-d28839de3af1', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'tesis-y-argumentos'),
  (select id from public.lotes where codigo = '2026-B'),
  '66bb3ca2-b0b4-45e9-b0b8-4837aa4eb278', 'Tesis y argumentos',
  'En el texto, el autor',
  array['usa cifras estadísticas para sostener una idea.', 'narra una escena trágica que sustenta su tesis.', 'usa una cita graciosa para apoyar una tesis.', 'incluye diálogos que prueban la idea principal.'],
  'Identifica la función de la cita con la que termina el pasaje.', 'publicada', 'modelo', '25db26d7e3a8f146cd7d78adc302e427', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('55586e49-e730-4fcc-8a2c-d28839de3af1', 2, 'La descripción despectiva del queso atribuida a un cortesano refuerza el ejemplo del rechazo cultural a los lácteos. No es un diálogo ni una estadística.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'b0296395-f4c4-4b92-8a1e-8bd7f0e1335e', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'estructura-textual'),
  (select id from public.lotes where codigo = '2026-B'),
  '66bb3ca2-b0b4-45e9-b0b8-4837aa4eb278', 'Estructura y articulación del texto',
  'A juzgar por su estilo y estructura, se podría decir que el texto anterior es parte de',
  array['una crónica periodística sobre el consumo global de leche.', 'un folleto publicitario acerca de una compañía de lácteos.', 'una novela histórica que ocurre durante la dinastía Ming.', 'un artículo científico de un seminario.'],
  'Considera el tono divulgativo y el recorrido por culturas y épocas.', 'publicada', 'modelo', '8309e11a297d31a9cee482cbaf97f218', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('b0296395-f4c4-4b92-8a1e-8bd7f0e1335e', 0, 'El pasaje combina explicaciones generales, referencias históricas y una anécdota con lenguaje valorativo, propio de una pieza periodística. No presenta una investigación científica formal ni una trama de novela.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'beeb5dc9-9b1f-4ee3-9462-7f10187d243a', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'proposito-del-texto'),
  (select id from public.lotes where codigo = '2026-B'),
  '66bb3ca2-b0b4-45e9-b0b8-4837aa4eb278', 'Propósito del texto',
  '¿Cuál de las siguientes opciones presenta un título adecuado para el texto?',
  array['Historia de la comida saludable.', 'Nuestro pan de cada día.', 'Hablemos de langostas.', 'La vida láctea.'],
  'Elige un título que abarque todo el pasaje sin cambiar su tema.', 'publicada', 'modelo', '650cfd271197c94fb569262cdffd231f', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('beeb5dc9-9b1f-4ee3-9462-7f10187d243a', 3, 'El asunto que conecta las regiones, la digestión y las anécdotas históricas es el consumo de leche y sus derivados. El título lácteo recoge ese tema específico.');

