insert into public.cuestionarios (id, materia, slug, seccion, titulo, tipo, orden, lote_id, publicado)
select '0262e25e-94a2-4915-8d28-ffdf8cbe0328', 'lc', 'lc-30', 'Información literal', 'Tintín · Información literal', 'Pasaje', 30,
